import{_ as a,o as i,c as s,ae as r}from"./chunks/framework.EHGTsUvI.js";const v=JSON.parse('{"title":"Discovery","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/discovery.md","filePath":"architecture/discovery.md"}'),t={name:"architecture/discovery.md"};function o(l,e,n,d,h,c){return i(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to &quot;Discovery&quot;">​</a></h1><h2 id="resolution-chain" tabindex="-1">Resolution Chain <a class="header-anchor" href="#resolution-chain" aria-label="Permalink to &quot;Resolution Chain&quot;">​</a></h2><p>When resolving a handle to a public key:</p><ol><li><strong>Local cache</strong> — In-memory + config file</li><li><strong>Discovery server</strong> — HTTP REST with signed responses</li><li><strong>DHT fallback</strong> — BEP 44 mutable lookup</li></ol><h2 id="discovery-servers" tabindex="-1">Discovery Servers <a class="header-anchor" href="#discovery-servers" aria-label="Permalink to &quot;Discovery Servers&quot;">​</a></h2><p>HTTP REST servers that provide:</p><ul><li><code>@handle</code> registration</li><li>Online/offline presence</li><li>Offline message inbox (relay)</li><li>Handle search/directory</li><li>Seeder listing</li></ul><h3 id="default-servers" tabindex="-1">Default Servers <a class="header-anchor" href="#default-servers" aria-label="Permalink to &quot;Default Servers&quot;">​</a></h3><p>Palexplorer ships with two discovery servers in Frankfurt:</p><ul><li><code>discovery-1.palexplorer.com</code></li><li><code>discovery-2.palexplorer.com</code></li></ul><h3 id="server-api" tabindex="-1">Server API <a class="header-anchor" href="#server-api" aria-label="Permalink to &quot;Server API&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /status</code></td><td>Server health</td></tr><tr><td><code>GET /resolve/:handle</code></td><td>Resolve handle to public key</td></tr><tr><td><code>GET /devices/:handle</code></td><td>List devices for handle</td></tr><tr><td><code>POST /register</code></td><td>Register handle (challenge-response)</td></tr><tr><td><code>POST /messages</code></td><td>Send offline message</td></tr><tr><td><code>GET /messages</code></td><td>Fetch offline messages</td></tr></tbody></table><h3 id="key-pinning" tabindex="-1">Key Pinning <a class="header-anchor" href="#key-pinning" aria-label="Permalink to &quot;Key Pinning&quot;">​</a></h3><p>On first connection, the server&#39;s fingerprint (SHA-256 of public key, first 8 chars) is stored. Future connections verify the fingerprint matches — prevents MITM attacks.</p><h3 id="custom-servers" tabindex="-1">Custom Servers <a class="header-anchor" href="#custom-servers" aria-label="Permalink to &quot;Custom Servers&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discovery_servers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://my-server.com</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://my-server.com</span></span></code></pre></div><p>You can run your own discovery server using <a href="https://github.com/hn2/palexplorer-server" target="_blank" rel="noreferrer">palexplorer-server</a>.</p><h2 id="dht-discovery" tabindex="-1">DHT Discovery <a class="header-anchor" href="#dht-discovery" aria-label="Permalink to &quot;DHT Discovery&quot;">​</a></h2><p>BitTorrent Mainline DHT with BEP 44:</p><ul><li><strong>Publish</strong>: <code>dht.put(publicKey, salt=&quot;pal:&lt;handle&gt;&quot;, value={h, pk, t, cap}, sign=ed25519)</code></li><li><strong>Resolve</strong>: <code>dht.get(target=sha1(pk+salt))</code> → verify Ed25519 signature → extract handle info</li></ul><h3 id="advantages-over-server" tabindex="-1">Advantages over Server <a class="header-anchor" href="#advantages-over-server" aria-label="Permalink to &quot;Advantages over Server&quot;">​</a></h3><ul><li>Decentralized — no single point of failure</li><li>Censorship-resistant</li><li>Works when discovery servers are down</li></ul><h3 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h3><ul><li>Slower than server (DHT lookup takes 5-15s)</li><li>Requires knowing the public key (can&#39;t search by handle)</li><li>No offline messaging</li><li>No presence information</li></ul><h2 id="federation" tabindex="-1">Federation <a class="header-anchor" href="#federation" aria-label="Permalink to &quot;Federation&quot;">​</a></h2><p>Multiple discovery servers can federate to share handle registrations:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> federation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> peer</span></span></code></pre></div><p>Cross-server handle resolution enables a decentralized network of discovery servers.</p>`,28)])])}const u=a(t,[["render",o]]);export{v as __pageData,u as default};
